param([string]$Worktree='wt-sol-1465-r4',[string]$Prefix='sig/handoff/rc144-r73-source')
# Documentation/source extraction only; no Go workload executes on the PC.
rg -n --no-heading '\.(Embed|EmbedBatch|EmbedWithInputType|EmbedBatchWithInputType|EmbedDocumentChunks|EmbedDocumentPropertyChunks|EmbedDocumentBatchChunks|EmbedDocumentPropertyBatchChunks|ChunkText|Model|Dimensions|Backend)\b' "$Worktree/pkg" "$Worktree/cmd" -g '*.go' -g '!**/*test.go' -g '!**/antlr/**' > "$Prefix-provider-uses.txt"
rg -n --no-heading 'NewEmbedder|newEmbedder|OwnEmbedder|SetEmbedder|SetDefaultEmbedConfig|SetEmbedConfigForDB|QueryEmbedderBinding|QueryEmbeddingSnapshot|WithQueryEmbeddingSnapshot|PrepareQueryEmbedding|ShareEmbedderFrom|\.Unwrap\(' "$Worktree/pkg" "$Worktree/cmd" -g '*.go' -g '!**/*test.go' -g '!**/antlr/**' > "$Prefix-entrypoints.txt"
rg -n --no-heading '\.(Close|Stop)\(|RunBackgroundTask|foregroundWg|ownedEmbedders|bgWg\.|buildCancel|embedderInitCancel|embedderInitDone|startWarmup|warmupStarted' "$Worktree/pkg/nornicdb" "$Worktree/pkg/server" "$Worktree/pkg/embed" "$Worktree/cmd" -g '*.go' -g '!**/*test.go' > "$Prefix-shutdown.txt"
rg -n --no-heading 'go func|onEmbedded|onQueueEmpty|ResultStreamStarted|FatalEmbeddingError|FatalSearchError|context\.Canceled|codes\.(Internal|Unavailable|Canceled)' "$Worktree/pkg/nornicdb/embed_queue.go" "$Worktree/pkg/cypher" "$Worktree/pkg/search/chunked_search.go" "$Worktree/pkg/nornicgrpc" "$Worktree/pkg/qdrantgrpc" "$Worktree/pkg/server/server_nornicdb.go" -g '*.go' -g '!**/*test.go' -g '!**/antlr/**' > "$Prefix-callbacks-fallback.txt"
# Function boundaries let each mechanically found selector be assigned to an entry path.
rg -n --no-heading '^func |^type .* (struct|interface)' "$Worktree/pkg/nornicdb/db_embedder_owner.go" "$Worktree/pkg/nornicdb/query_embedding.go" "$Worktree/pkg/nornicdb/embed_queue.go" "$Worktree/pkg/cypher/query_embedder.go" "$Worktree/pkg/cypher/query_embed_chunk.go" "$Worktree/pkg/server/server_heimdall.go" "$Worktree/pkg/nornicgrpc/search_service.go" > "$Prefix-boundaries.txt"